  if (grade <= 20) return SPHERE_REST_Y[0];
  if (grade >= 50) return SPHERE_REST_Y[3];
  const t = (grade - 20) / 30;
  return SPHERE_REST_Y[0] + (SPHERE_REST_Y[3] - SPHERE_REST_Y[0]) * t;
