  return { group, glass, oil, oilMat, glassMat };
}

// ── Sphere builder ──
function buildSphere(x, y) {
  const geo = new THREE.SphereGeometry(0.34, 32, 32);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x888899, metalness: 0.9, roughness: 0.3
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, 0);
  scene.add(mesh);
  return mesh;
}

// Build cylinders
const cylinders = GRADES.map((g, i) => buildCylinder(CYL_X[i], OIL_COLORS[i], g));

// Build spheres
const spheres = GRADES.map((g, i) => buildSphere(CYL_X[i], SPHERE_REST_Y[i]));

// ── Probe sphere (for slider) ──
const probeGeo = new THREE.SphereGeometry(0.34, 32, 32);
const probeMat = new THREE.MeshStandardMaterial({
  color: 0x888899, metalness: 0.9, roughness: 0.3,
  emissive: 0x333344, emissiveIntensity: 0.3
});
const probeSphere = new THREE.Mesh(probeGeo, probeMat);
probeSphere.visible = false;
scene.add(probeSphere);

// ── Labels ──
const gradeLabels = GRADES.map((g, i) => {
  return addLabel(String(g), new THREE.Vector3(CYL_X[i], -0.55, 1.15), { fontSize: '14px', bold: true });
});

addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.55, 1.15), { fontSize: '13px' });

// Terminal velocity labels (hidden by default)
const velLabels = GRADES.map((g, i) => {
  const lbl = addLabel(`v<sub>t</sub> = ${TERM_VEL[i].toFixed(1)} cm/s`, new THREE.Vector3(CYL_X[i] + 0.6, SPHERE_REST_Y[i], 0), {
    fontSize: '11px', color: '#333', background: 'rgba(255,255,255,0.85)'
  });
  lbl.div.style.display = 'none';
  return lbl;
});

// ── State ──
let animating = false;
let animTime = 0;
let showVel = false;
let probeActive = false;
let probeGrade = 30;
let probeY = SPHERE_START_Y;

// ── Animation ──
const ANIM_DURATION = 6; // seconds for full drop
const PAUSE_DURATION = 1.5; // pause at bottom before loop

function getSphereY(grade, t) {
  // t goes from 0 to 1 during drop phase
  const idx = GRADES.indexOf(grade);
  const restY = idx >= 0 ? SPHERE_REST_Y[idx] : interpolateRestY(grade);
  const startY = SPHERE_START_Y;
  // Terminal velocity determines speed: higher grade = slower
  const vel = getTermVel(grade);
  const maxVel = TERM_VEL[0]; // 3.0
  const speedFactor = vel / maxVel;
  // Sphere falls proportionally to speed
  const progress = Math.min(1, t * speedFactor * 2.5);
  const eased = 1 - Math.pow(1 - progress, 2); // ease out
  return startY + (restY - startY) * eased;
}

function getTermVel(grade) {
  // Interpolate terminal velocity between grades
  if (grade <= 20) return 3.0;
  if (grade >= 50) return 1.0;
  const t = (grade - 20) / 30;
  return 3.0 + (1.0 - 3.0) * t;
}

function interpolateRestY(grade) {
  if (grade <= 20) return SPHERE_REST_Y[0];
  if (grade >= 50) return SPHERE_REST_Y[3];
  const t = (grade - 20) / 30;
  return SPHERE_REST_Y[0] + (SPHERE_REST_Y[3] - SPHERE_REST_Y[0]) * t;
}

function interpolateColor(grade) {
  const t = (grade - 20) / 30;
  const c1 = new THREE.Color(OIL_COLORS[0]);
  const c4 = new THREE.Color(OIL_COLORS[3]);
  return c1.lerp(c4, t);
}

// ── UI wiring ──
const btnDrop = document.getElementById('dropRace');
const sliderGrade = document.getElementById('saeGrade');
const sliderVal = document.getElementById('saeGradeVal');
const chkVel = document.getElementById('showVelocity');

btnDrop.addEventListener('click', () => {
  animating = !animating;
  btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
  btnDrop.classList.toggle('active', animating);
  if (animating) animTime = 0;
});

sliderGrade.addEventListener('input', () => {
  probeGrade = parseInt(sliderGrade.value);
  sliderVal.textContent = probeGrade;
  probeActive = true;
  probeSphere.visible = true;
  // Place probe in the nearest tube
  const nearestIdx = Math.round((probeGrade - 20) / 10);
  const clampedIdx = Math.max(0, Math.min(3, nearestIdx));
  probeSphere.position.x = CYL_X[clampedIdx];
  probeSphere.position.z = 0;
  // Interpolate y based on grade
  probeY = interpolateRestY(probeGrade);
  probeSphere.position.y = probeY;
  // Highlight the nearest tube's oil
  cylinders.forEach((c, i) => {
    if (i === clampedIdx) {
      c.oilMat.emissive = new THREE.Color(0x222200);
      c.oilMat.emissiveIntensity = 0.2;
    } else {
      c.oilMat.emissive = new THREE.Color(0x000000);
      c.oilMat.emissiveIntensity = 0;
    }
  });
  // Update velocity label for probe
  const vel = getTermVel(probeGrade);
  velLabels.forEach((l, i) => {
    if (i === clampedIdx && showVel) {
      l.div.style.display = '';
      l.div.innerHTML = `v<sub>t</sub> = ${vel.toFixed(1)} cm/s`;
      l.pos.set(CYL_X[i] + 0.6, probeSphere.position.y, 0);
    }
  });
});

chkVel.addEventListener('change', () => {
  showVel = chkVel.checked;
  velLabels.forEach((l, i) => {
    if (showVel) {
      l.div.style.display = '';
      l.pos.set(CYL_X[i] + 0.6, spheres[i].position.y, 0);
    } else {
      l.div.style.display = 'none';
    }
  });
});

// ── Demo steps ──
function goToStep(idx) {
  const steps = [
    { showVelocity: false, animating: false, animTime: 0 },
    { showVelocity: false, animating: true, animTime: 2.5 },
    { showVelocity: true, animating: true, animTime: 4.0 },
    { showVelocity: true, animating: false, saeGrade: 45 }
  ];
  const s = steps[idx];
  if (s.showVelocity !== undefined) {
    chkVel.checked = s.showVelocity;
    chkVel.dispatchEvent(new Event('change'));
  }
  if (s.animating !== undefined) {
    animating = s.animating;
    btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
    btnDrop.classList.toggle('active', animating);
  }
  if (s.animTime !== undefined) animTime = s.animTime;
  if (s.saeGrade !== undefined) {
    sliderGrade.value = s.saeGrade;
    sliderGrade.dispatchEvent(new Event('input'));
  }
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(3));

// ── Render loop extension ──
const _origAnimate = animate;
let _clock = new THREE.Clock();

function updateAnimation() {
  if (animating) {
    animTime += _clock.getDelta();
    const cycleTime = ANIM_DURATION + PAUSE_DURATION;
    const t = (animTime % cycleTime) / ANIM_DURATION;
    const clampedT = Math.min(1, Math.max(0, t));

    spheres.forEach((s, i) => {
      s.position.y = getSphereY(GRADES[i], clampedT);
      if (showVel) {
        velLabels[i].pos.set(CYL_X[i] + 0.6, s.position.y, 0);
      }
    });
  } else {
    _clock.getDelta(); // consume delta
  }
}

// Patch into the existing animate loop by overriding
const _baseAnimate = window.requestAnimationFrame;
let _patched = false;
if (!_patched) {
  _patched = true;
  const origRAF = window.requestAnimationFrame.bind(window);
  // We'll use a simpler approach: just update in a setInterval-like manner
  setInterval(updateAnimation, 16);
}

// ── Camera view ──
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});

// ── Interactive registration ──
spheres.forEach((s, i) => {
  registerInteractive(s, {
    title: `SAE ${GRADES[i]} sphere`,
    body: `Terminal velocity: ${TERM_VEL[i].toFixed(1)} cm/s. Higher viscosity means slower descent.`,
    tooltip: `SAE ${GRADES[i]} — v_t = ${TERM_VEL[i].toFixed(1)} cm/s`
  });
});

cylinders.forEach((c, i) => {
  registerInteractive(c.glass, {
    title: `SAE ${GRADES[i]} oil`,
    body: `Oil color indicates viscosity grade. SAE ${GRADES[i]} has terminal velocity ${TERM_VEL[i].toFixed(1)} cm/s for the test sphere.`,
    tooltip: `SAE ${GRADES[i]} oil`
  });
});
// @FIGURE_CODE_END

