Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="dropRace">▶ Drop all spheres</button>
<label>SAE grade
  <input type="range" id="saeGrade" min="20" max="50" step="1" value="30">
  <span id="saeGradeVal">30</span>
</label>
<label style="flex-direction:row;align-items:center;gap:4px;">
  <input type="checkbox" id="showVelocity"> Terminal velocity labels
</label>
<button id="btnStep0">Step 1: Release</button>
<button id="btnStep1">Step 2: Mid-descent</button>
<button id="btnStep2">Step 3: Steady descent</button>
<button id="btnStep3">Step 4: Sweep grade</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──────────────────────────────────────────────────────────
// base slab      → BoxGeometry(8, 0.4, 2.2) gold top #d9a83a, red front #cc3322
// cylinder glass → CylinderGeometry(0.42, 0.42, 4.0, 32, 1, true) transparent #cfe0ea
// cylinder oil   → CylinderGeometry(0.34, 0.34, 3.3, 32) opaque per-grade color
// meniscus       → CircleGeometry(0.34, 32) at oil top
// pedestal       → CylinderGeometry(0.55, 0.55, 0.25, 6) grey #b0b8c0
// spout lip      → TorusGeometry(0.42, 0.03, 8, 32) at top rim
// sphere         → SphereGeometry(0.34, 32, 32) metallic grey
// ──────────────────────────────────────────────────────────────────────────

const GRADES = [20, 30, 40, 50];
const OIL_COLORS = [0xf1d98c, 0xe9bd52, 0xe69a5e, 0xe05a48];
const SPHERE_REST_Y = [1.0, 1.5, 2.1, 2.6];
const TERM_VEL = [3.0, 2.2, 1.5, 1.0];
const CYL_X = [-3.0, -1.0, 1.0, 3.0];
const SPHERE_START_Y = 3.4;

// Lighting
const ambLight = new THREE.AmbientLight(0xffffff, 0.65);
scene.add(ambLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(2, 6, 5);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
dirLight2.position.set(-2, 4, -3);
scene.add(dirLight2);

// ── Base slab ──
const baseTopMat = new THREE.MeshStandardMaterial({ color: 0xd9a83a, roughness: 0.6 });
const baseFrontMat = new THREE.MeshStandardMaterial({ color: 0xcc3322, roughness: 0.5 });
const baseSideMat = new THREE.MeshStandardMaterial({ color: 0xd9a83a, roughness: 0.6 });
const baseMats = [baseSideMat, baseSideMat, baseTopMat, baseSideMat, baseFrontMat, baseSideMat];
const baseGeo = new THREE.BoxGeometry(8, 0.4, 2.2);
const baseMesh = new THREE.Mesh(baseGeo, baseMats);
baseMesh.position.set(0, -0.2, 0);
scene.add(baseMesh);

// ── Cylinder builder ──
function buildCylinder(x, oilColor, grade) {
  const group = new THREE.Group();
  group.position.set(x, 0, 0);

  const pedGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.25, 6);
  const pedMat = new THREE.MeshStandardMaterial({ color: 0xb0b8c0, roughness: 0.4, metalness: 0.3 });
  const ped = new THREE.Mesh(pedGeo, pedMat);
  ped.position.y = 0.125;
  group.add(ped);

  const glassGeo = new THREE.CylinderGeometry(0.42, 0.42, 4.0, 32, 1, true);
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: 0xcfe0ea, transparent: true, opacity: 0.25,
    roughness: 0.1, metalness: 0.0, side: THREE.DoubleSide
  });
  const glass = new THREE.Mesh(glassGeo, glassMat);
  glass.position.y = 2.0;
  group.add(glass);

  const capGeo = new THREE.CircleGeometry(0.42, 32);
  const capMat = new THREE.MeshPhysicalMaterial({
    color: 0xcfe0ea, transparent: true, opacity: 0.3, side: THREE.DoubleSide
  });
  const cap = new THREE.Mesh(capGeo, capMat);
  cap.rotation.x = -Math.PI / 2;
  cap.position.y = 0.01;
  group.add(cap);

  const oilHeight = 3.3;
  const oilGeo = new THREE.CylinderGeometry(0.34, 0.34, oilHeight, 32, 1, false);
  const oilMat = new THREE.MeshStandardMaterial({ color: oilColor, roughness: 0.4, transparent: true, opacity: 0.9 });
  const oil = new THREE.Mesh(oilGeo, oilMat);
  oil.position.y = 0.3 + oilHeight / 2;
  group.add(oil);

  const menGeo = new THREE.CircleGeometry(0.34, 32);
  const menMat = new THREE.MeshStandardMaterial({ color: oilColor, roughness: 0.3, transparent: true, opacity: 0.7 });
  const men = new THREE.Mesh(menGeo, menMat);
  men.rotation.x = -Math.PI / 2;
  men.position.y = 0.3 + oilHeight + 0.01;
  group.add(men);

  const spoutGeo = new THREE.TorusGeometry(0.42, 0.03, 8, 32);
  const spoutMat = new THREE.MeshStandardMaterial({ color: 0xb0b8c0, roughness: 0.3, metalness: 0.4 });
  const spout = new THREE.Mesh(spoutGeo, spoutMat);
  spout.rotation.x = Math.PI / 2;
  spout.position.y = 4.0;
  group.add(spout);

  const spoutLipGeo = new THREE.ConeGeometry(0.08, 0.15, 8);
  const spoutLip = new THREE.Mesh(spoutLipGeo, spoutMat.clone());
  spoutLip.position.set(0.45, 4.05, 0);
  spoutLip.rotation.z = -Math.PI / 4;
  group.add(spoutLip);

  scene.add(group);
  return { group, glass, oil, oilMat, glassMat };
}

// ── Sphere builder ──
function buildSphere(x, y) {
  const geo = new THREE.SphereGeometry(0.34, 32, 32);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x888899, metalness: 0.9, roughness: 0.3
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, 0);
  scene.add(mesh);
  return mesh;
}

const cylinders = GRADES.map((g, i) => buildCylinder(CYL_X[i], OIL_COLORS[i], g));
const spheres = GRADES.map((g, i) => buildSphere(CYL_X[i], SPHERE_REST_Y[i]));

// ── Probe sphere ──
const probeGeo = new THREE.SphereGeometry(0.34, 32, 32);
const probeMat = new THREE.MeshStandardMaterial({
  color: 0x888899, metalness: 0.9, roughness: 0.3,
  emissive: 0x333344, emissiveIntensity: 0.3
});
const probeSphere = new THREE.Mesh(probeGeo, probeMat);
probeSphere.visible = false;
scene.add(probeSphere);

// ── Static labels (always visible) ──
GRADES.forEach((g, i) => {
  addLabel(String(g), new THREE.Vector3(CYL_X[i], -0.55, 1.15), { fontSize: '14px', bold: true });
});
addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.55, 1.15), { fontSize: '13px' });

// ── Velocity labels: manual divs (NOT via addLabel) so we control visibility ──
const velLabelDivs = GRADES.map((g, i) => {
  const div = document.createElement('div');
  div.className = 'lbl';
  div.innerHTML = `v<sub>t</sub> = ${TERM_VEL[i].toFixed(1)} cm/s`;
  div.style.fontSize = '11px';
  div.style.color = '#333';
  div.style.background = 'rgba(255,255,255,0.85)';
  div.style.padding = '1px 4px';
  div.style.borderRadius = '3px';
  div.style.display = 'none';
  _stage.appendChild(div);
  return { div, pos: new THREE.Vector3(CYL_X[i] + 0.6, SPHERE_REST_Y[i], 0) };
});

function updateVelLabelPositions() {
  const v = new THREE.Vector3();
  for (const vl of velLabelDivs) {
    if (vl.div.style.display === 'none') continue;
    v.copy(vl.pos).project(camera);
    if (v.z > 1 || v.z < -1 || v.x < -1 || v.x > 1 || v.y < -1 || v.y > 1) {
      vl.div.style.display = 'none';
      continue;
    }
    const x = canvas.offsetLeft + (v.x * 0.5 + 0.5) * canvas.clientWidth;
    const y = canvas.offsetTop + (-v.y * 0.5 + 0.5) * canvas.clientHeight;
    vl.div.style.left = x + 'px';
    vl.div.style.top = y + 'px';
  }
}

// ── State ──
let animating = false;
let animTime = 0;
let showVel = false;
let probeActive = false;
let probeGrade = 30;

const ANIM_DURATION = 6;
const PAUSE_DURATION = 1.5;

function getTermVel(grade) {
  if (grade <= 20) return 3.0;
  if (grade >= 50) return 1.0;
  return 3.0 + (1.0 - 3.0) * ((grade - 20) / 30);
}

function interpolateRestY(grade) {
  if (grade <= 20) return SPHERE_REST_Y[0];
  if (grade >= 50) return SPHERE_REST_Y[3];
  return SPHERE_REST_Y[0] + (SPHERE_REST_Y[3] - SPHERE_REST_Y[0]) * ((grade - 20) / 30);
}

function getSphereY(grade, t) {
  const restY = interpolateRestY(grade);
  const vel = getTermVel(grade);
  const speedFactor = vel / 3.0;
  const progress = Math.min(1, t * speedFactor * 2.5);
  const eased = 1 - Math.pow(1 - progress, 2);
  return SPHERE_START_Y + (restY - SPHERE_START_Y) * eased;
}

// ── UI wiring ──
const btnDrop = document.getElementById('dropRace');
const sliderGrade = document.getElementById('saeGrade');
const sliderVal = document.getElementById('saeGradeVal');
const chkVel = document.getElementById('showVelocity');

btnDrop.addEventListener('click', () => {
  animating = !animating;
  btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
  btnDrop.classList.toggle('active', animating);
  if (animating) animTime = 0;
});

sliderGrade.addEventListener('input', () => {
  probeGrade = parseInt(sliderGrade.value);
  sliderVal.textContent = probeGrade;
  probeActive = true;
  probeSphere.visible = true;
  const nearestIdx = Math.max(0, Math.min(3, Math.round((probeGrade - 20) / 10)));
  probeSphere.position.x = CYL_X[nearestIdx];
  probeSphere.position.z = 0;
  probeSphere.position.y = interpolateRestY(probeGrade);
  cylinders.forEach((c, i) => {
    if (i === nearestIdx) {
      c.oilMat.emissive = new THREE.Color(0x222200);
      c.oilMat.emissiveIntensity = 0.2;
    } else {
      c.oilMat.emissive = new THREE.Color(0x000000);
      c.oilMat.emissiveIntensity = 0;
    }
  });
});

chkVel.addEventListener('change', () => {
  showVel = chkVel.checked;
  velLabelDivs.forEach((vl, i) => {
    if (showVel) {
      vl.div.style.display = '';
      vl.pos.set(CYL_X[i] + 0.6, spheres[i].position.y, 0);
    } else {
      vl.div.style.display = 'none';
    }
  });
});

// ── Demo steps ──
function goToStep(idx) {
  const steps = [
    { showVelocity: false, animating: false, animTime: 0 },
