      vl.pos.set(CYL_X[i] + 0.6, spheres[i].position.y, 0);
    } else {
      vl.div.style.display = 'none';
    }
  });
});

// ── Demo steps ──
function goToStep(idx) {
  const steps = [
    { showVelocity: false, animating: false, animTime: 0 },
    { showVelocity: false, animating: true, animTime: 2.5 },
    { showVelocity: true, animating: true, animTime: 4.0 },
    { showVelocity: true, animating: false, saeGrade: 45 }
  ];
  const s = steps[idx];
  if (s.showVelocity !== undefined) {
    chkVel.checked = s.showVelocity;
    chkVel.dispatchEvent(new Event('change'));
  }
  if (s.animating !== undefined) {
    animating = s.animating;
    btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
    btnDrop.classList.toggle('active', animating);
  }
  if (s.animTime !== undefined) animTime = s.animTime;
  if (s.saeGrade !== undefined) {
    sliderGrade.value = s.saeGrade;
    sliderGrade.dispatchEvent(new Event('input'));
  }
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(3));

// ── Animation update ──
let _clock = new THREE.Clock();
function updateAnimation() {
  if (animating) {
    animTime += _clock.getDelta();
    const cycleTime = ANIM_DURATION + PAUSE_DURATION;
    const t = Math.min(1, Math.max(0, (animTime % cycleTime) / ANIM_DURATION));
    spheres.forEach((s, i) => {
      s.position.y = getSphereY(GRADES[i], t);
      if (showVel) {
        velLabelDivs[i].pos.set(CYL_X[i] + 0.6, s.position.y, 0);
      }
    });
  } else {
    _clock.getDelta();
  }
  updateVelLabelPositions();
}
setInterval(updateAnimation, 16);

// ── Camera: near-frontal to match source ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 10,
  heightFraction: 0.72
});

// ── Interactive registration ──
spheres.forEach((s, i) => {
  registerInteractive(s, {
    title: `SAE ${GRADES[i]} sphere`,
    body: `Terminal velocity: ${TERM_VEL[i].toFixed(1)} cm/s. Higher viscosity means slower descent.`,
    tooltip: `SAE ${GRADES[i]} — v_t = ${TERM_VEL[i].toFixed(1)} cm/s`
  });
});

cylinders.forEach((c, i) => {
  registerInteractive(c.glass, {
    title: `SAE ${GRADES[i]} oil`,
    body: `Oil color indicates viscosity grade. SAE ${GRADES[i]} has terminal velocity ${TERM_VEL[i].toFixed(1)} cm/s for the test sphere.`,
    tooltip: `SAE ${GRADES[i]} oil`
  });
});
// @FIGURE_CODE_END

