Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="dropRace">▶ Drop all spheres</button>
<label>SAE grade
  <input type="range" id="saeGrade" min="20" max="50" step="1" value="30">
  <span id="saeGradeVal">30</span>
</label>
<label style="flex-direction:row;align-items:center;gap:4px;">
  <input type="checkbox" id="showVelocity"> Terminal velocity labels
</label>
<button id="btnStep0">Step 1: Release</button>
<button id="btnStep1">Step 2: Mid-descent</button>
<button id="btnStep2">Step 3: Steady descent</button>
<button id="btnStep3">Step 4: Sweep grade</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──────────────────────────────────────────────────────────
// base slab      → BoxGeometry(8, 0.5, 2.4) gold top #d4a030, red front #cc2211
// cylinder glass → CylinderGeometry(0.42, 0.42, 4.0, 32, 1, true) transparent #d8e8f0
// cylinder oil   → CylinderGeometry(0.34, 0.34, 3.3, 32) vibrant per-grade color
// meniscus       → CircleGeometry(0.34, 32) at oil top
// pedestal       → CylinderGeometry(0.55, 0.55, 0.25, 6) grey #a8b0b8
// spout lip      → TorusGeometry(0.42, 0.03, 8, 32) at top rim
// sphere         → SphereGeometry(0.34, 32, 32) bright metallic silver #c8d0d8
// ──────────────────────────────────────────────────────────────────────────

const GRADES = [20, 30, 40, 50];
// Vibrant colors matching source: pale yellow → golden → orange → bright red
const OIL_COLORS = [0xf5e8a0, 0xedc44e, 0xf09848, 0xe84030];
const SPHERE_REST_Y = [1.0, 1.5, 2.1, 2.6];
const TERM_VEL = [3.0, 2.2, 1.5, 1.0];
const CYL_X = [-3.0, -1.0, 1.0, 3.0];
const SPHERE_START_Y = 3.4;

// Lighting - brighter to make colors pop
const ambLight = new THREE.AmbientLight(0xffffff, 0.7);
scene.add(ambLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.9);
dirLight.position.set(3, 8, 5);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.35);
dirLight2.position.set(-3, 5, -4);
scene.add(dirLight2);
const dirLight3 = new THREE.DirectionalLight(0xffffff, 0.2);
dirLight3.position.set(0, 3, 6);
scene.add(dirLight3);

// ── Base slab ──
const baseTopMat = new THREE.MeshStandardMaterial({ color: 0xd4a030, roughness: 0.5, metalness: 0.1 });
const baseFrontMat = new THREE.MeshStandardMaterial({ color: 0xcc2211, roughness: 0.4 });
const baseSideMat = new THREE.MeshStandardMaterial({ color: 0xd4a030, roughness: 0.5, metalness: 0.1 });
const baseMats = [baseSideMat, baseSideMat, baseTopMat, baseSideMat, baseFrontMat, baseSideMat];
const baseGeo = new THREE.BoxGeometry(8, 0.5, 2.4);
const baseMesh = new THREE.Mesh(baseGeo, baseMats);
baseMesh.position.set(0, -0.25, 0);
scene.add(baseMesh);

// ── Cylinder builder ──
function buildCylinder(x, oilColor, grade) {
  const group = new THREE.Group();
  group.position.set(x, 0, 0);

  // Hexagonal pedestal
  const pedGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.25, 6);
  const pedMat = new THREE.MeshStandardMaterial({ color: 0xa8b0b8, roughness: 0.35, metalness: 0.3 });
  const ped = new THREE.Mesh(pedGeo, pedMat);
  ped.position.y = 0.125;
  group.add(ped);

  // Glass wall - very transparent so oil shows through
  const glassGeo = new THREE.CylinderGeometry(0.42, 0.42, 4.0, 32, 1, true);
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: 0xd8e8f0, transparent: true, opacity: 0.18,
    roughness: 0.05, metalness: 0.0, side: THREE.DoubleSide
  });
  const glass = new THREE.Mesh(glassGeo, glassMat);
  glass.position.y = 2.0;
  group.add(glass);

  // Bottom cap
  const capGeo = new THREE.CircleGeometry(0.42, 32);
  const capMat = new THREE.MeshPhysicalMaterial({
    color: 0xd8e8f0, transparent: true, opacity: 0.25, side: THREE.DoubleSide
  });
  const cap = new THREE.Mesh(capGeo, capMat);
  cap.rotation.x = -Math.PI / 2;
  cap.position.y = 0.01;
  group.add(cap);

  // Oil column - vibrant and mostly opaque
  const oilHeight = 3.3;
  const oilGeo = new THREE.CylinderGeometry(0.34, 0.34, oilHeight, 32, 1, false);
  const oilMat = new THREE.MeshStandardMaterial({
    color: oilColor, roughness: 0.35, transparent: true, opacity: 0.92
  });
  const oil = new THREE.Mesh(oilGeo, oilMat);
  oil.position.y = 0.3 + oilHeight / 2;
  group.add(oil);

  // Meniscus
  const menGeo = new THREE.CircleGeometry(0.34, 32);
  const menMat = new THREE.MeshStandardMaterial({
    color: oilColor, roughness: 0.25, transparent: true, opacity: 0.8
  });
  const men = new THREE.Mesh(menGeo, menMat);
  men.rotation.x = -Math.PI / 2;
  men.position.y = 0.3 + oilHeight + 0.01;
  group.add(men);

  // Spout ring at top
  const spoutGeo = new THREE.TorusGeometry(0.42, 0.03, 8, 32);
  const spoutMat = new THREE.MeshStandardMaterial({ color: 0xa8b0b8, roughness: 0.3, metalness: 0.4 });
  const spout = new THREE.Mesh(spoutGeo, spoutMat);
  spout.rotation.x = Math.PI / 2;
  spout.position.y = 4.0;
  group.add(spout);

  // Spout lip (pouring spout)
  const spoutLipGeo = new THREE.ConeGeometry(0.08, 0.18, 8);
  const spoutLip = new THREE.Mesh(spoutLipGeo, spoutMat.clone());
  spoutLip.position.set(0.48, 4.06, 0);
  spoutLip.rotation.z = -Math.PI / 4;
  group.add(spoutLip);

  scene.add(group);
  return { group, glass, oil, oilMat, glassMat };
}

// ── Sphere builder - bright metallic silver for contrast ──
function buildSphere(x, y) {
  const geo = new THREE.SphereGeometry(0.34, 32, 32);
  const mat = new THREE.MeshStandardMaterial({
    color: 0xc8d0d8, metalness: 0.95, roughness: 0.12,
    envMapIntensity: 1.2
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, 0);
  scene.add(mesh);
  return mesh;
}

const cylinders = GRADES.map((g, i) => buildCylinder(CYL_X[i], OIL_COLORS[i], g));
const spheres = GRADES.map((g, i) => buildSphere(CYL_X[i], SPHERE_REST_Y[i]));

// ── Probe sphere ──
const probeGeo = new THREE.SphereGeometry(0.34, 32, 32);
const probeMat = new THREE.MeshStandardMaterial({
  color: 0xd0d8e0, metalness: 0.95, roughness: 0.1,
  emissive: 0x222233, emissiveIntensity: 0.2
});
const probeSphere = new THREE.Mesh(probeGeo, probeMat);
probeSphere.visible = false;
scene.add(probeSphere);

// ── Static labels ──
GRADES.forEach((g, i) => {
  addLabel(String(g), new THREE.Vector3(CYL_X[i], -0.7, 1.25), { fontSize: '14px', bold: true });
});
addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.7, 1.25), { fontSize: '13px' });

// ── Velocity labels ──
const velLabelDivs = GRADES.map((g, i) => {
  const div = document.createElement('div');
  div.className = 'lbl';
  div.innerHTML = `v<sub>t</sub> = ${TERM_VEL[i].toFixed(1)} cm/s`;
  div.style.fontSize = '11px';
  div.style.color = '#222';
  div.style.background = 'rgba(255,255,255,0.9)';
  div.style.padding = '1px 5px';
  div.style.borderRadius = '3px';
  div.style.display = 'none';
  _stage.appendChild(div);
  return { div, pos: new THREE.Vector3(CYL_X[i] + 0.65, SPHERE_REST_Y[i], 0) };
});

function updateVelLabelPositions() {
  const v = new THREE.Vector3();
  for (const vl of velLabelDivs) {
    if (vl.div.style.display === 'none') continue;
    v.copy(vl.pos).project(camera);
    if (v.z > 1 || v.z < -1 || v.x < -1 || v.x > 1 || v.y < -1 || v.y > 1) {
      vl.div.style.display = 'none';
      continue;
    }
    const x = canvas.offsetLeft + (v.x * 0.5 + 0.5) * canvas.clientWidth;
    const y = canvas.offsetTop + (-v.y * 0.5 + 0.5) * canvas.clientHeight;
    vl.div.style.left = x + 'px';
    vl.div.style.top = y + 'px';
  }
}

// ── State ──
let animating = false;
let animTime = 0;
let showVel = false;
let probeActive = false;
let probeGrade = 30;

const ANIM_DURATION = 6;
const PAUSE_DURATION = 1.5;

function getTermVel(grade) {
  if (grade <= 20) return 3.0;
  if (grade >= 50) return 1.0;
  return 3.0 + (1.0 - 3.0) * ((grade - 20) / 30);
}

function interpolateRestY(grade) {
  if (grade <= 20) return SPHERE_REST_Y[0];
  if (grade >= 50) return SPHERE_REST_Y[3];
  return SPHERE_REST_Y[0] + (SPHERE_REST_Y[3] - SPHERE_REST_Y[0]) * ((grade - 20) / 30);
}

function getSphereY(grade, t) {
  const restY = interpolateRestY(grade);
  const vel = getTermVel(grade);
  const speedFactor = vel / 3.0;
  const progress = Math.min(1, t * speedFactor * 2.5);
  const eased = 1 - Math.pow(1 - progress, 2);
  return SPHERE_START_Y + (restY - SPHERE_START_Y) * eased;
}

// ── UI wiring ──
const btnDrop = document.getElementById('dropRace');
const sliderGrade = document.getElementById('saeGrade');
const sliderVal = document.getElementById('saeGradeVal');
const chkVel = document.getElementById('showVelocity');

btnDrop.addEventListener('click', () => {
  animating = !animating;
  btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
  btnDrop.classList.toggle('active', animating);
  if (animating) animTime = 0;
});

sliderGrade.addEventListener('input', () => {
  probeGrade = parseInt(sliderGrade.value);
  sliderVal.textContent = probeGrade;
  probeActive = true;
  probeSphere.visible = true;
  const nearestIdx = Math.max(0, Math.min(3, Math.round((probeGrade - 20) / 10)));
  probeSphere.position.x = CYL_X[nearestIdx];
  probeSphere.position.z = 0;
  probeSphere.position.y = interpolateRestY(probeGrade);
  cylinders.forEach((c, i) => {
    if (i === nearestIdx) {
      c.oilMat.emissive = new THREE.Color(0x333300);
      c.oilMat.emissiveIntensity = 0.25;
    } else {
      c.oilMat.emissive = new THREE.Color(0x000000);
      c.oilMat.emissiveIntensity = 0;
    }
  });
});

chkVel.addEventListener('change', () => {
  showVel = chkVel.checked;
  velLabelDivs.forEach((vl, i) => {
    if (showVel) {
      vl.div.style.display = '';
      vl.pos.set(CYL_X[i] + 0.65, spheres[i].position.y, 0);
    } else {
      vl.div.style.display = 'none';
    }
  });
});

// ── Demo steps ──
function goToStep(idx) {
  const steps = [
    { showVelocity: false, animating: false, animTime: 0 },
    { showVelocity: false, animating: true, animTime: 2.5 },
    { showVelocity: true, animating: true, animTime: 4.0 },
    { showVelocity: true, animating: false, saeGrade: 45 }
  ];
  const s = steps[idx];
  if (s.showVelocity !== undefined) {
    chkVel.checked = s.showVelocity;
    chkVel.dispatchEvent(new Event('change'));
  }
  if (s.animating !== undefined) {
    animating = s.animating;
    btnDrop.textContent = animating ? '⏸ Pause' : '▶ Drop all spheres';
    btnDrop.classList.toggle('active', animating);
  }
  if (s.animTime !== undefined) animTime = s.animTime;
  if (s.saeGrade !== undefined) {
    sliderGrade.value = s.saeGrade;
    sliderGrade.dispatchEvent(new Event('input'));
  }
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(3));

// ── Animation update ──
let _clock = new THREE.Clock();
function updateAnimation() {
  if (animating) {
    animTime += _clock.getDelta();
    const cycleTime = ANIM_DURATION + PAUSE_DURATION;
    const t = Math.min(1, Math.max(0, (animTime % cycleTime) / ANIM_DURATION));
    spheres.forEach((s, i) => {
      s.position.y = getSphereY(GRADES[i], t);
      if (showVel) {
        velLabelDivs[i].pos.set(CYL_X[i] + 0.65, s.position.y, 0);
      }
    });
  } else {
    _clock.getDelta();
  }
  updateVelLabelPositions();
}
setInterval(updateAnimation, 16);

// ── Camera: slightly elevated to show base top face ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 18,
  heightFraction: 0.72
});

// ── Interactive registration ──
spheres.forEach((s, i) => {
  registerInteractive(s, {
    title: `SAE ${GRADES[i]} sphere`,
    body: `Terminal velocity: ${TERM_VEL[i].toFixed(1)} cm/s. Higher viscosity means slower descent.`,
    tooltip: `SAE ${GRADES[i]} — v_t = ${TERM_VEL[i].toFixed(1)} cm/s`
  });
});

cylinders.forEach((c, i) => {
  registerInteractive(c.glass, {
    title: `SAE ${GRADES[i]} oil`,
    body: `Oil color indicates viscosity grade. SAE ${GRADES[i]} has terminal velocity ${TERM_VEL[i].toFixed(1)} cm/s for the test sphere.`,
    tooltip: `SAE ${GRADES[i]} oil`
  });
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

